Definition bp_arm37_stmt (pc pc' : Z) (st : Z) (W : Z -> Z -> Z -> Z -> Z -> list (Z * Z))
    (shA : Z -> Z -> Z -> list cell) (ffrA : Z -> Z -> list byte -> list byte -> list byte -> list byte -> list byte -> list byte -> list byte -> list cell) : Prop :=
  forall (rax : word) (spa lo : Z) (gp tp t0 t1 t2 sp0 a0 a1 a2 a3 a4 a5 a6 a7 : word) (E P ff fp n : Z)
         (t3 t4 t5 t6 : word) (F : bvmap 5 word) fc (m : mem) (c : pcore) (pad7 pad2 j0 j128 j152 ja j48 jb j80 jc j112 : list byte)
         (p0 p1 p : Z) (s1b s2b : Z) (rdi : byte) (E1 : ecv),
  rw_cells bsegs m P (ParserCoreCells c pad7 pad2) -> pcore_ok c -> pc_state c = st ->
  rw_cells bsegs m spa (bp_locals E P p0 ff j0 j128 j152 p) ->
  rw_cells bsegs m ff (bp_ffr spa fp ja j48 jb j80 jc j112) ->
  rw_cells bsegs m (sh ff) (shA F8b s1b s2b) ->
  rw_cells bsegs m (P + 240) [C1 rdi] ->
  rw_cells bsegs m E (ErrCodeCells E1) ->
  AXStatics2 m ->
  stk bsegs m lo spa -> aceil <= lo -> lo + OBINIT_STACK <= spa -> spa + 184 < 2^64 ->
  accessible m P 344 -> P mod 8 = 0 -> aapp P 344 -> aapp E 24 -> E mod 8 = 0 -> (P + 344 <= E \/ E + 24 <= P) ->
  0 <= ff -> ff mod 64 = 0 -> aapp ff 128 -> Z.shiftr ff 3 + 2147450880 = sh ff -> 0x800c8800 <= sh ff -> sh ff + 16 <= AHI_LO ->
  (P + 344 <= ff \/ ff + 128 <= P) -> (E + 24 <= ff \/ ff + 128 <= E) ->
  mem_inv bsegs m -> ACONST m -> accessible m E 24 -> shvis m E (E + 24) ->
  evt bsegs (fun ms' => exists rax' t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' m' ja',
       ms' = bp_ms pc' rax' spa gp tp t0' t1' t2' sp0 a0' a1' a2' a3' a4' a5' a6' a7' E P ff p1 n t3' t4' t5' t6' F fc m'
       /\ munch (W lo spa ff E P) m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
       /\ stk bsegs m' lo spa
       /\ rw_cells bsegs m' P (ParserCoreCells c pad7 pad2)
       /\ rw_cells bsegs m' ff (ffrA spa fp ja' ja j48 jb j80 jc j112)
       /\ rw_cells bsegs m' (sh ff) (shA F8b s1b s2b)
       /\ rw_cells bsegs m' (P + 240) [C1 (b8 1)]
       /\ rw_cells bsegs m' E (ErrCodeCells EC_clear))
    (bp_ms pc rax spa gp tp t0 t1 t2 sp0 a0 a1 a2 a3 a4 a5 a6 a7 E P ff p1 n t3 t4 t5 t6 F fc m).

